# owner: platform
"""Lay students out in rows, sorted by last name."""
from typing import List
from rosterkit.models import Student

def _sort_key(person: Student):
    return (person.last_name.lower(),
            person.first_name.lower())

def _row_line(group: List[Student], number: int) -> str:
    names = " | ".join(
        f"{item.last_name}, {item.first_name}"
        for item in group
    )
    return f"Row {number}: {names}"

# ---
def seat_rows(students, seats):
    if seats < 1 or not students:
        raise ValueError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    starts = range(0, len(ordered), seats)
    return [_row_line(ordered[start:start + seats], number)
            for number, start in enumerate(starts, 1)]

