# owner: platform
import unittest
from rosterkit.seating import seat_rows
from rosterkit.models import Student

def build_student(last, first):
    return Student("id", last, first, "A")

class SeatingTests(unittest.TestCase):
    # ---
    def test_sorted_and_split_into_rows(self):
        people = [
            build_student("Halloway", "Juno"),
            build_student("Dunmere", "Piet"),
            build_student("Abbot", "Ola")
        ]
        self.assertEqual(seat_rows(people, 2), [
            "Row 1: Abbot, Ola | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    # ---
    def test_bad_seat_count_raises(self):
        people = [build_student("Abbot", "Ola")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(people, seats)

    # ---
    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
